# Generated by Cursor (plan: inline typo word[: correction]; plan: , [: correction])
"""Scan for editorial markup word[: correction] and word, [: correction]; replace with correction."""

import re

# word then optional space, [ : then non-] chars then ]
INLINE_TYPO_RE = re.compile(r"\b(\w+)\s*\[\s*:\s*([^\]]+)\]")
# word, [: correction] -> replace typo + bracket with "correction,"
INLINE_TYPO_COMMA_RE = re.compile(r"\b(\w+),\s*\[\s*:\s*([^\]]+)\]")
# , [: correction] alone
INLINE_TYPO_COMMA_ONLY_RE = re.compile(r",\s*\[\s*:\s*([^\]]+)\]")


def scan_turn_inline_typo(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (inline_typo, start_index, full_span, path_str) for word[: correction] and , [: correction]."""
    result: list[tuple[str, int, str, str]] = []
    seen_starts: set[int] = set()
    for rex in (INLINE_TYPO_RE, INLINE_TYPO_COMMA_RE, INLINE_TYPO_COMMA_ONLY_RE):
        for m in rex.finditer(text):
            if m.start() not in seen_starts:
                seen_starts.add(m.start())
                result.append(("inline_typo", m.start(), m.group(0), path_str))
    return result
